import { useEffect, useMemo, useRef, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { SegmentedControl } from "@/shared/ui/controls/SegmentedControl";
import { Toggle } from "@/shared/ui/controls/Toggle";
import { SearchField } from "@/shared/ui/controls/SearchField";
import { StatusDot } from "@/shared/ui/feedback/StatusDot";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";

// A component composing 2+ first-party FEATURE-level sibling cross-imports (PullIntoPlanControl,
// PlannerComponentsPane) alongside several shared/ui ones reliably fails to build in this sandbox
// ("no implementation source — stored source is only a usage snippet"), the same failure mode
// ClaudeConfigCard hit composing 5 settings-cards siblings. Inlined both bodies locally instead.

// PullIntoPlanControl — inlined verbatim from the promoted `pullintoplancontrol` component.
function featureRequires(feature, artifactId) {
  return (feature.requires ?? []).includes(artifactId);
}
function pullIntoPlan(projectKey, feature, artifactId) {
  return new Promise((resolve) => {
    setTimeout(() => {
      const requires = featureRequires(feature, artifactId) ? (feature.requires ?? []) : [...(feature.requires ?? []), artifactId];
      resolve(requires);
    }, 400);
  });
}
const SAMPLE_FEATURES = [
  { slug: "checkout-flow", name: "Checkout flow", requires: [] },
  { slug: "inventory-sync", name: "Inventory sync", requires: ["merge-sort.rs"] },
  { slug: "order-history", name: "Order history", requires: [] },
];
function PullIntoPlanControl({ projectKey = "northwind", features = SAMPLE_FEATURES, artifactId = "merge-sort.rs" }) {
  const [pulled, setPulled] = useState(new Set());
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(null);

  if (features.length === 0) {
    return (
      <Text tone="dim" size={10.5}>
        No features yet — the plan needs a capability before a library record can be attached to one.
      </Text>
    );
  }

  const pull = async (feature) => {
    setError(null);
    setBusy(feature.slug);
    try {
      await pullIntoPlan(projectKey, feature, artifactId);
      setPulled((s) => new Set(s).add(feature.slug));
    } catch (e) {
      setError(`Couldn't record it on "${feature.name}" — ${e instanceof Error ? e.message : String(e)}`);
    } finally {
      setBusy(null);
    }
  };

  return (
    <Stack gap={4}>
      <Text tone="dim" size={10.5}>Build a feature from this — the worker gets the id, not a copy</Text>
      <Box style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
        {features.map((f) => {
          const already = featureRequires(f, artifactId) || pulled.has(f.slug);
          return (
            <Button
              key={f.slug}
              size="sm"
              variant={already ? "default" : "ghost"}
              disabled={already || busy === f.slug}
              onClick={() => void pull(f)}
              title={already ? `"${f.name}" already requires ${artifactId}` : `Build "${f.name}" from ${artifactId}`}
            >
              {already ? "✓ " : "+ "}{f.name}
            </Button>
          );
        })}
      </Box>
      {error && <Text tone="danger" size={10.5}>{error}</Text>}
    </Stack>
  );
}

// PlannerComponentsPane — inlined verbatim from the promoted `plannercomponentspane` component.
const NO_COMPONENTS_TITLE = "No components yet";
const ROLE_COLOR = {
  primitive: "var(--info)", composite: "var(--accent)", layout: "var(--violet)", page: "var(--success)", service: "var(--state-wait, var(--accent))",
};
function matchesQuery(c, query) {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return c.name.toLowerCase().includes(q) || c.role.includes(q);
}
function RoleDot({ role, size = 8 }) {
  return <StatusDot color={ROLE_COLOR[role]} size={size} />;
}
function KitChip({ kit, on, className, title, onClick }) {
  return (
    <Box as="button" className={`${className}${on ? " on" : ""}`} title={title} onClick={onClick}
      style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "3px 9px", borderRadius: 99, cursor: "pointer",
        border: "1px solid " + (on ? "var(--accent)" : "var(--border-soft)"), background: on ? "color-mix(in oklch, var(--accent), transparent 88%)" : "var(--bg-elev)",
        color: on ? "var(--fg)" : "var(--fg-muted)", fontSize: 11 }}>
      <ColorSwatch color={kit.dot} size={6} />{kit.name}
    </Box>
  );
}
const ROLE_RANK = { page: 0, layout: 1, composite: 2, primitive: 3, service: 4 };
const ASSEMBLE_MAX = 6;
const TOAST_MS = 1900;
function Specimen({ comp, height }) {
  return (
    <Box style={{ display: "flex", alignItems: "center", justifyContent: "center", width: "100%", height: height ?? "100%", minHeight: 40, padding: 10, pointerEvents: "none", borderRadius: 8, background: "var(--bg-elev, var(--bg-soft))", border: "1px dashed var(--border-soft)" }}>
      <RoleDot role={comp.role} size={12} />
    </Box>
  );
}
const DEFAULT_KITS = [
  { id: "react-ui", name: "react-ui", stack: "React · TypeScript", dot: "var(--accent)" },
];
const DEFAULT_COMPONENTS = [
  { id: "c1", name: "Button", kitId: "react-ui", role: "primitive", props: [{ name: "variant", type: '"primary" | "ghost"', req: false, desc: "" }], whenUse: ["Any clickable primary action"], whenNot: ["A navigation link — use Link"] },
  { id: "c2", name: "Card", kitId: "react-ui", role: "composite", props: [{ name: "interactive", type: "boolean", req: false, desc: "" }], whenUse: ["Grouping related content"], whenNot: ["A single line of text"] },
  { id: "c3", name: "ProjectsPage", kitId: "react-ui", role: "page", props: [], whenUse: ["The top-level projects screen"], whenNot: [] },
  { id: "c4", name: "Grid", kitId: "react-ui", role: "layout", props: [], whenUse: ["A responsive column layout"], whenNot: [] },
];
const NOOP = () => {};
function PlannerComponentsPane() {
  const [components] = useState(DEFAULT_COMPONENTS);
  const [kits] = useState(DEFAULT_KITS);
  const navigate = NOOP;

  const [kitId, setKitId] = useState(() => kits[0]?.id ?? "");
  const [mode, setMode] = useState("components");
  const [query, setQuery] = useState("");
  const [openId, setOpenId] = useState(null);
  const [highlight, setHighlight] = useState(true);
  const [toast, setToast] = useState(null);
  const toastTimer = useRef(undefined);
  useEffect(() => () => { if (toastTimer.current) clearTimeout(toastTimer.current); }, []);

  const flash = (msg) => {
    setToast(msg);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(null), TOAST_MS);
  };

  const kit = kits.find((k) => k.id === kitId) ?? kits[0];
  const inKit = useMemo(() => components.filter((c) => c.kitId === kitId), [components, kitId]);
  const list = useMemo(() => inKit.filter((c) => matchesQuery(c, query)), [inKit, query]);
  const assembled = useMemo(
    () => [...inKit].sort((a, b) => ROLE_RANK[a.role] - ROLE_RANK[b.role]).slice(0, ASSEMBLE_MAX),
    [inKit],
  );

  const openInStudio = () => navigate();

  if (!kit) {
    return (
      <Box>
        <EmptyState size="sm" title={NO_COMPONENTS_TITLE} description="The proven-component library is empty — seed a kit to browse it here." />
      </Box>
    );
  }

  return (
    <Box>
      <Box style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
        <Box style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <Text weight={600} size={13}>Components</Text>
          <Box style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <Text mono size="xxs" tone="dim">ACTIVE KIT{kits.length > 1 ? "S" : ""}</Text>
            {kits.map((k) => (
              <KitChip key={k.id} kit={k} on={k.id === kitId} className="pcp-kitchip" title={k.stack}
                onClick={() => { setKitId(k.id); setOpenId(null); }} />
            ))}
          </Box>
        </Box>
        <SegmentedControl
          label=""
          options={[
            { label: "▤ Components", on: mode === "components", onClick: () => setMode("components") },
            { label: "▦ Full UI", on: mode === "full", onClick: () => setMode("full") },
          ]}
        />
      </Box>

      {mode === "components" ? (
        <>
          <Box style={{ marginTop: 10 }}>
            <SearchField
              value={query}
              onChange={setQuery}
              placeholder="Search components this app needs..."
              aria-label="Search components"
              inputStyle={{ fontSize: 12 }}
              trailing={<Text mono size="xxs" tone="dim">{list.length}/{inKit.length}</Text>}
            />
          </Box>

          <Box style={{ marginTop: 10, display: "flex", flexDirection: "column", gap: 8 }}>
            {list.map((c) => {
              const open = openId === c.id;
              return (
                <Box key={c.id}>
                  <Box as="button" onClick={() => setOpenId(open ? null : c.id)} style={{
                    width: "100%", display: "flex", alignItems: "center", gap: 10, padding: 10, borderRadius: 8,
                    border: "1px solid " + (open ? "var(--accent)" : "var(--border-soft)"), background: "var(--bg-elev)", cursor: "pointer", textAlign: "left",
                  }}>
                    <Box style={{ width: 40 }}><Specimen comp={c} height={40} /></Box>
                    <Box style={{ flex: 1, minWidth: 0 }}>
                      <Box style={{ display: "flex", alignItems: "center", gap: 7 }}>
                        <RoleDot role={c.role} size={7} />
                        <Text weight={600} size={12.5}>{c.name}</Text>
                      </Box>
                      <Text mono size="xxs" tone="dim" as="div" style={{ marginTop: 3 }}>{kit.name} · {c.role}</Text>
                    </Box>
                    <Text as="span" style={{ fontSize: 10.5, color: "var(--success)" }}>in library ✓</Text>
                  </Box>

                  {open && (
                    <Box style={{ padding: "12px 14px", border: "1px solid var(--border-soft)", borderTop: "none", borderRadius: "0 0 8px 8px" }}>
                      <Box style={{ display: "flex", flexDirection: "column", gap: 5, marginBottom: 13 }}>
                        {c.props.slice(0, 4).map((p) => (
                          <Box key={p.name} style={{ display: "flex", justifyContent: "space-between" }}>
                            <Text mono tone="muted" size={11.5}>{p.name}</Text><Text mono tone="accent" size={10.5}>{p.type}</Text>
                          </Box>
                        ))}
                        {c.props.length === 0 && <Text mono size={11} tone="dim">No public props.</Text>}
                      </Box>
                      <Box style={{ display: "flex", gap: 10 }}>
                        <Button variant="primary" size="sm" onClick={() => flash(`"${c.name}" added to the plan`)} style={{ flex: 1 }}>Pull into plan</Button>
                        <Button variant="ghost" size="sm" onClick={openInStudio}>Open in studio ↗</Button>
                      </Box>
                    </Box>
                  )}
                </Box>
              );
            })}
            {list.length === 0 && (
              <Text size={11.5} tone="dim" as="div" style={{ padding: "10px 2px", fontStyle: "italic" }}>No components match "{query}".</Text>
            )}
          </Box>
        </>
      ) : (
        <Box style={{ marginTop: 10 }}>
          <Box style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <Text size={11.5} tone="muted">Assembled from <b style={{ color: "var(--fg)" }}>{assembled.length}</b> kit components</Text>
            <Box style={{ display: "flex", alignItems: "center", gap: 7 }}>
              <Toggle size="sm" on={highlight} onClick={() => setHighlight((h) => !h)} role="switch" ariaChecked={highlight} />
              <Text size={11} tone="muted">highlight</Text>
            </Box>
          </Box>
          <Box style={{ marginTop: 12, display: "flex", flexDirection: "column", gap: 6 }}>
            {assembled.map((c, i) => (
              <Box as="button" key={c.id} onClick={() => { setMode("components"); setOpenId(c.id); }} style={{
                display: "flex", alignItems: "center", gap: 8, padding: 8, borderRadius: 6, background: "var(--bg-elev)", border: "none", cursor: "pointer", width: "100%", textAlign: "left",
              }}>
                <Box as="span" style={{ width: 18, height: 18, borderRadius: "50%", background: ROLE_COLOR[c.role], color: "var(--bg-canvas)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10.5 }}>{i + 1}</Box>
                <Text size={12} weight={500}>{c.name}</Text>
                <Text mono size="xxs" tone="dim">{c.role}</Text>
              </Box>
            ))}
          </Box>
        </Box>
      )}

      {toast && (
        <Box style={{ position: "absolute", bottom: 12, left: 12, right: 12, display: "flex", alignItems: "center", gap: 8, padding: 10, borderRadius: 8, background: "var(--bg-elev2)", border: "1px solid var(--border-soft)" }}>
          <StatusDot color="var(--success)" size={7} />
          <Text size={12}>{toast}</Text>
        </Box>
      )}
    </Box>
  );
}

// Preview-only stand-in for `PlannerAlgorithmsPane` (from `@/features/algorithms`, out of this
// vendoring pass's scope — a whole separate librarian/knowledge-graph browser).
function PlannerAlgorithmsPane({ pullControl }) {
  return (
    <Box style={{ padding: 16, textAlign: "center" }}>
      <Text tone="dim" size={11.5}>Algorithms lens — browse the knowledge-graph library here.</Text>
      {pullControl && <Box style={{ marginTop: 10 }}>{pullControl("merge-sort.rs")}</Box>}
    </Box>
  );
}

const TABS = [
  { value: "components", label: "Components" },
  { value: "algorithms", label: "Algorithms" },
];

export function PlannerLibraryPane({
  initial = "components", projectKey = "northwind", features,
}) {
  const [tab, setTab] = useState(initial);
  const pullControl = projectKey
    ? (artifactId) => (
        <PullIntoPlanControl projectKey={projectKey} features={features ?? []} artifactId={artifactId} />
      )
    : undefined;
  return (
    <Stack gap={0} style={{ flex: 1, minHeight: 0, position: "relative" }}>
      <Box style={{ padding: "8px 10px 0" }}>
        <SegmentedControl
          options={TABS.map((t) => ({ label: t.label, on: tab === t.value, onClick: () => setTab(t.value) }))}
        />
      </Box>
      <Box style={{ display: "flex", flex: 1, minHeight: 0, flexDirection: "column", padding: 10 }}>
        {tab === "components"
          ? <PlannerComponentsPane pullControl={pullControl} />
          : <PlannerAlgorithmsPane pullControl={pullControl} />}
      </Box>
    </Stack>
  );
}
